MATCH p=(a:Issue)-[:BLOCKER|BONFIRE_TESTING|CAUSE|CLONERS|DEPENDS|DERIVED|DETAIL|DUPLICATE|FOLLOWS|PART|REFERENCE|REGRESSION|RELATE|RELATED|RESOLVE|SPLIT|SUPERSESSION*1..5]-(b:Issue)
WITH nodes(p) AS ns, relationships(p) AS rs
WHERE size(ns)=size(rs)+1 AND all(i IN range(0,size(ns)-1) WHERE NOT ns[i] IN ns[i+1..]) AND all(i IN range(0,size(rs)-1) WHERE exists{(ns[i])-[:ASSIGNED_TO]->(x:Person), (ns[i+1])-[:ASSIGNED_TO]->(y:Person) WHERE x<>y})
AND NOT exists{ MATCH (ns[0])-[:BLOCKER|BONFIRE_TESTING|CAUSE|CLONERS|DEPENDS|DERIVED|DETAIL|DUPLICATE|FOLLOWS|PART|REFERENCE|REGRESSION|RELATE|RELATED|RESOLVE|SPLIT|SUPERSESSION]-(f:Issue) WHERE NOT f IN ns AND exists{(ns[0])-[:ASSIGNED_TO]->(x:Person), (f)-[:ASSIGNED_TO]->(y:Person) WHERE x<>y} }
AND NOT exists{ MATCH (ns[-1])-[:BLOCKER|BONFIRE_TESTING|CAUSE|CLONERS|DEPENDS|DERIVED|DETAIL|DUPLICATE|FOLLOWS|PART|REFERENCE|REGRESSION|RELATE|RELATED|RESOLVE|SPLIT|SUPERSESSION]-(f:Issue) WHERE NOT f IN ns AND exists{(ns[-1])-[:ASSIGNED_TO]->(x:Person), (f)-[:ASSIGNED_TO]->(y:Person) WHERE x<>y} }
RETURN [n IN ns|n.issueKey] AS path, [r IN rs|r.linkId] AS links

MATCH p=(a:Issue)((u:Issue)-[r:BLOCKER|BONFIRE_TESTING|CAUSE|CLONERS|DEPENDS|DERIVED|DETAIL|DUPLICATE|FOLLOWS|PART|REFERENCE|REGRESSION|RELATE|RELATED|RESOLVE|SPLIT|SUPERSESSION]-(v:Issue) WHERE exists{(u)-[:ASSIGNED_TO]->(x:Person), (v)-[:ASSIGNED_TO]->(y:Person) WHERE x<>y}){1,5}(b:Issue)
WITH a,b,nodes(p) AS ns, relationships(p) AS rs
WHERE all(i IN range(0,size(ns)-1) WHERE NOT ns[i] IN ns[i+1..])
AND NOT exists{ MATCH (a)-[:BLOCKER|BONFIRE_TESTING|CAUSE|CLONERS|DEPENDS|DERIVED|DETAIL|DUPLICATE|FOLLOWS|PART|REFERENCE|REGRESSION|RELATE|RELATED|RESOLVE|SPLIT|SUPERSESSION]-(f:Issue) WHERE NOT f IN ns AND exists{(a)-[:ASSIGNED_TO]->(x:Person), (f)-[:ASSIGNED_TO]->(y:Person) WHERE x<>y} }
AND NOT exists{ MATCH (b)-[:BLOCKER|BONFIRE_TESTING|CAUSE|CLONERS|DEPENDS|DERIVED|DETAIL|DUPLICATE|FOLLOWS|PART|REFERENCE|REGRESSION|RELATE|RELATED|RESOLVE|SPLIT|SUPERSESSION]-(f:Issue) WHERE NOT f IN ns AND exists{(b)-[:ASSIGNED_TO]->(x:Person), (f)-[:ASSIGNED_TO]->(y:Person) WHERE x<>y} }
RETURN [n IN ns|n.issueKey] AS path, [r IN rs|r.linkId] AS links, [n IN ns|head([(n)-[:IN_PROJECT]->(p) | p.projectKey])] AS projs

MATCH p=(a:Issue)((u:Issue)-[r:BLOCKER|BONFIRE_TESTING|CAUSE|CLONERS|DEPENDS|DERIVED|DETAIL|DUPLICATE|FOLLOWS|PART|REFERENCE|REGRESSION|RELATE|RELATED|RESOLVE|SPLIT|SUPERSESSION]-(v:Issue) WHERE exists{(u)-[:ASSIGNED_TO]->(x:Person), (v)-[:ASSIGNED_TO]->(y:Person) WHERE x<>y}){1,5}(b:Issue)
WITH a,b,nodes(p) AS ns, relationships(p) AS rs
WHERE all(i IN range(0,size(ns)-1) WHERE NOT ns[i] IN ns[i+1..])
AND NOT exists{ MATCH (a)-[:BLOCKER|BONFIRE_TESTING|CAUSE|CLONERS|DEPENDS|DERIVED|DETAIL|DUPLICATE|FOLLOWS|PART|REFERENCE|REGRESSION|RELATE|RELATED|RESOLVE|SPLIT|SUPERSESSION]-(f:Issue) WHERE NOT f IN ns AND exists{(a)-[:ASSIGNED_TO]->(x:Person), (f)-[:ASSIGNED_TO]->(y:Person) WHERE x<>y} }
AND NOT exists{ MATCH (b)-[:BLOCKER|BONFIRE_TESTING|CAUSE|CLONERS|DEPENDS|DERIVED|DETAIL|DUPLICATE|FOLLOWS|PART|REFERENCE|REGRESSION|RELATE|RELATED|RESOLVE|SPLIT|SUPERSESSION]-(f:Issue) WHERE NOT f IN ns AND exists{(b)-[:ASSIGNED_TO]->(x:Person), (f)-[:ASSIGNED_TO]->(y:Person) WHERE x<>y} }
RETURN [n IN ns|n.issueKey] AS path, [i IN range(0,size(rs)-1) | [ns[i].issueKey, ns[i+1].issueKey]] AS hops, [r IN rs|[r.linkId]] AS links
